from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    base=Counter(v for row in grid for v in row).most_common(1)[0][0]
    row_modes=[Counter(row).most_common(1)[0][0] for row in grid]
    col_modes=[Counter(grid[r][c] for r in range(h)).most_common(1)[0][0] for c in range(w)]
    def rare_mode(modes):
        counts=Counter(modes)
        return min(counts, key=lambda x: (counts[x], x))
    rsep,csep=rare_mode(row_modes),rare_mode(col_modes)
    rs=[i for i,v in enumerate(row_modes) if v==rsep]
    cs=[i for i,v in enumerate(col_modes) if v==csep]
    out=[]
    for ri in range(len(rs)-1):
        row=[]
        for ci in range(len(cs)-1):
            vals=(grid[rs[ri]][cs[ci]],grid[rs[ri]][cs[ci+1]],grid[rs[ri+1]][cs[ci]],grid[rs[ri+1]][cs[ci+1]])
            v=vals[0] if len(set(vals))==1 and vals[0] not in (base,rsep,csep) else base
            row.append(v)
        out.append(row)
    while len(out)>1 and all(v==base for v in out[0]): out.pop(0)
    while len(out)>1 and all(v==base for v in out[-1]): out.pop()
    while len(out[0])>1 and all(row[0]==base for row in out):
        out=[row[1:] for row in out]
    while len(out[0])>1 and all(row[-1]==base for row in out):
        out=[row[:-1] for row in out]
    return out

